import { Directive, ElementRef, inject, input, type DoCheck, type Type } from '@angular/core'

import { memberAt } from './member'

/**
 * The states fixture: an Angular member's `*.states.ts`, generated by
 * `pnpm shells` from the member's description (`packages/shells/src/members/`).
 *
 * The entries carry the React fixture's names, so a contract's `when <state>`
 * names the same entry in every shell. The fixture is one component that
 * renders the entry its `entry` input names, by its position, and hands its
 * `overrides` input (a probe name, a spy in a handler, by the React prop's
 * name) to the member the entry renders first, over the fixture's own props.
 */
export interface StateEntry {
  name: string
  /** Attributes the rendered root must carry. `null` asserts absence. */
  expect?: Readonly<Record<string, string | null>>
  /** The entry renders nothing at all, by design. */
  rendersNothing?: true
}

export interface ComponentStates {
  component: string
  /** The fixture component: inputs `entry` (the entry's position) and `overrides`. */
  fixture: Type<unknown>
  entries: readonly StateEntry[]
}

/**
 * Sets the conformance runner's props and handlers on the member on the same
 * element, over its own and its slot's: `<pm-button [pmOverrides]="overrides()">`.
 * A handler it sets replaces the caller's binding, as a React fixture's spread
 * props replace its own.
 */
@Directive({ selector: '[pmOverrides]' })
export class Overrides implements DoCheck {
  readonly pmOverrides = input<Readonly<Record<string, unknown>>>({})
  private readonly element = inject(ElementRef).nativeElement as Element

  ngDoCheck(): void {
    const member = memberAt(this.element)
    const overrides = this.pmOverrides()
    if (member !== undefined && member.overrides() !== overrides)
      member.overrides.set(Object.keys(overrides).length === 0 ? null : overrides)
  }
}
